export function LobbyPage() {
  const navigate = useNavigate(); const [tab, setTab] = useState<"today" | "current">("today"); const [data, setData] = useState<{ counts: Record<string, number>; items: LobbyVisitor[]; truncated?: boolean; limit?: number }>({ counts: {}, items: [] }); const [error, setError] = useState(""); const [connected, setConnected] = useState(false);
  const [query, setQuery] = useState(""); const [lobbyFilter, setLobbyFilter] = useState("");
  const { user } = useAuth();
  const [reference, setReference] = useState<ReferenceData | null>(null);
  const scope = user?.role === "lobby" ? (user.siteScope ?? []) : [];
  const lobbies = (reference?.lobbies ?? []).filter((x) => scope.length === 0 || scope.includes(x.siteId));
  useEffect(() => { api<ReferenceData>("/api/v1/reference-data").then(setReference).catch(() => undefined); }, []);
  const [manual, setManual] = useState<LobbyVisitor | null>(null); const [manualReason, setManualReason] = useState(""); const [manualBadge, setManualBadge] = useState("");
  const load = useCallback(async () => { try { const params = new URLSearchParams({ q: query }); if (lobbyFilter) params.set("lobby", lobbyFilter); setData(await api(`/api/v1/lobby/${tab}?${params}`)); } catch (e) { setError(e instanceof Error ? e.message : "로비 현황을 불러오지 못했습니다"); } }, [tab, query, lobbyFilter]);
  // A visitor without a working phone is still expected; admit them after an
